import { atom, read, update } from "claude-code";
import type { EngineInterface, Register } from "claude-code";

import type { FleetAgent, FleetShell, FleetState } from "../types";
import {
  applyStatuses,
  emptyFleet,
  endShell,
  endToast,
  fmtLeft,
  isFailed,
  isLive,
  isWaiter,
  lastLine,
  liveCount,
  loseShells,
  mayNotify,
  nextProgress,
  outputFileOf,
  parseNotification,
  parseProgress,
  parseStatus,
  parseWorktrees,
  quietMs,
  shellName,
  shellNotes,
  STALL_MS,
  statusLine,
  summary,
  toolLabel,
  trim,
} from "./core.ts";
import { drawFleet, type FleetView } from "./view.tsx";

const PANE = "fleet";
const ENDED = new Set(["completed", "failed", "killed"]);
const TOAST_GAP_MS = 2_100;
const SHELL_POLL_MS = 5_000;
/** Bytes of a shell's output read for its last line. */
const TAIL_BYTES = "4096";

const fleet = atom({ plugin: "fleet", key: "fleet" } as const, emptyFleet());
const pane = atom({ plugin: "fleet", key: "pane" } as const, false);
const lastPrompt = atom({ plugin: "fleet", key: "lastPrompt" } as const, 0);

/** What the module keeps outside `$.state`; a reload starts it over. */
type Tracker = {
  autoOpen: boolean;
  sound: boolean;
  telegram: boolean;
  idleMs: number;
  repo: string;
  root: string | undefined;
  /** Whether the surface docks a pane beside the transcript, as the band last drew; unknown until then. */
  docks: boolean | undefined;
  poll: { cancel: () => void } | undefined;
  /** The look at live shells' output, while any has an output file. */
  shellPoll: { cancel: () => void } | undefined;
  /** When the band was last redrawn for a stalled shell's quiet time. */
  quietDrawnAt: number;
};

function chime($: EngineInterface, sound: "complete" | "dialog-error") {
  // $.audio has no player on a Linux terminal; paplay does
  void $.process
    .run(["paplay", `/usr/share/sounds/freedesktop/stereo/${sound}.oga`])
    .catch(() => undefined);
}

async function sendTelegram($: EngineInterface, text: string): Promise<void> {
  const none = () => undefined;
  const token = await $.env.get("TELEGRAM_BOT_TOKEN").catch(none);
  const chat = await $.env.get("TELEGRAM_CHAT_ID").catch(none);
  if (!token || !chat) return;
  const res = await $.http
    .fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ chat_id: chat, text }),
    })
    .catch(none);
  if (!res?.ok)
    $.ui.log(`fleet: Telegram send failed (${res?.status ?? "no response"})`, {
      to: "debug",
    });
}

/** Whether the engine draws the pane: `isShown` is false behind other tabs, so not asked. */
async function isPaneDrawn($: EngineInterface): Promise<boolean> {
  const panes = await $.ui.panes().catch(() => []);
  return panes.some((p) => p.id === PANE && p.isPlaced);
}

async function refreshTrees($: EngineInterface, t: Tracker): Promise<void> {
  if (!t.root) return;
  const list = await $.process
    .run(["git", "worktree", "list", "--porcelain"], { cwd: t.root })
    .catch(() => undefined);
  if (!list || list.exitCode !== 0) return;
  const trees = await Promise.all(
    parseWorktrees(list.stdout).map(async (w) => {
      const st = await $.process
        .run(["git", "status", "--porcelain=v1", "--branch"], { cwd: w.path })
        .catch(() => undefined);
      const counts =
        st && st.exitCode === 0
          ? parseStatus(st.stdout)
          : { changed: 0, ahead: 0, behind: 0 };
      return { ...w, ...counts };
    }),
  );
  await update($, fleet, (f) => ({ ...f, trees }));
}

/** One toast for everything that just ended (a toast replaces the plugin's last); a chime for a failure. */
function announce(
  $: EngineInterface,
  t: Tracker,
  agents: FleetAgent[],
  shells: FleetShell[],
) {
  const ended = [
    // a teammate gone idle is no finish
    ...agents
      .filter((a) => ENDED.has(a.status))
      .map((a) => ({ ...a, name: a.type, what: a.description })),
    ...shells.map((s) => ({ ...s, name: "shell", what: s.command })),
  ].map((x) => ({
    text: endToast(x.name, x.what, x.status, x.endedAt! - x.startedAt),
    isFailed: isFailed(x.status),
  }));
  if (ended.length === 0) return;
  $.ui.toast(
    ended.length === 1
      ? ended[0]!.text
      : `${ended.length} finished: ${[
          ...ended.slice(0, 3).map((x) => x.text),
          ...(ended.length > 3 ? [`+${ended.length - 3} more`] : []),
        ].join("; ")}`,
  );
  if (t.sound && ended.some((x) => x.isFailed)) chime($, "dialog-error");
}

/** When nothing is live any more: the all-done alert, and the batch closes. */
async function settle($: EngineInterface, t: Tracker): Promise<void> {
  const f = await read($, fleet);
  if (liveCount(f) > 0) return;
  t.poll?.cancel();
  t.poll = undefined;
  if (f.batchStart === undefined) return;

  const batch = f.batchStart;
  const size =
    f.agents.filter((a) => a.startedAt >= batch).length +
    f.shells.filter((s) => s.startedAt >= batch).length;
  const now = await $.clock.now();
  const text = summary(f, t.repo, now);
  await update($, fleet, ({ batchStart: _, ...g }) => ({
    ...g,
    autoOpened: false,
  }));
  // one item's own toast says it all; the all-done alert is for a batch
  if (size >= 2) {
    // the engine drops a toast within 2 s of the last, and the last item's just showed
    const done = text.split("\n").slice(1, 3).join(" · ");
    $.clock.after(TOAST_GAP_MS, () => $.ui.toast(done));
    if (t.sound) chime($, "complete");
  }
  if (t.telegram && now - (await read($, lastPrompt)) >= t.idleMs)
    await sendTelegram($, text);
}

/** One look at `$.agent.list()`: status changes, their alerts, maybe all done. */
async function tick($: EngineInterface, t: Tracker): Promise<void> {
  const list = await $.agent.list().catch(() => undefined);
  if (!list) return;
  const statuses = Object.fromEntries(list.map((a) => [a.id, a.status]));
  let ended: FleetAgent[] = [];
  await update($, fleet, (f) => {
    const r = applyStatuses(f.agents, statuses, Date.now());
    ended = r.ended;
    return { ...f, agents: r.agents };
  });
  announce($, t, ended, []);
  await settle($, t);
}

function ensurePoll($: EngineInterface, t: Tracker) {
  if (!t.poll) t.poll = $.clock.every(2000, () => void tick($, t));
}

/** One look at each live shell's output: its last line, progress, or a stall. */
async function watchShells($: EngineInterface, t: Tracker): Promise<void> {
  const live = (await read($, fleet)).shells.filter(
    (s) => isLive(s.status) && s.outputFile,
  );
  if (live.length === 0) {
    t.shellPoll?.cancel();
    t.shellPoll = undefined;
    return;
  }
  const now = await $.clock.now();
  const patches = new Map<string, Partial<FleetShell>>();
  const stalled: FleetShell[] = [];
  for (const s of live) {
    const st = await $.fs.stat(s.outputFile!).catch(() => undefined);
    if (st?.kind === "file" && st.size !== s.size) {
      const tail = await $.process
        .run(["tail", "-c", TAIL_BYTES, s.outputFile!])
        .catch(() => undefined);
      const line = tail?.exitCode === 0 ? lastLine(tail.stdout) : undefined;
      patches.set(s.id, {
        size: st.size,
        outputAt: now,
        stalled: false,
        ...(line
          ? { line, progress: nextProgress(s.progress, parseProgress(line), now) }
          : {}),
      });
    } else if (!s.waiter && !s.stalled && quietMs(s, now) >= STALL_MS) {
      patches.set(s.id, { stalled: true });
      stalled.push(s);
    }
  }
  if (patches.size > 0)
    await update($, fleet, (f) => ({
      ...f,
      shells: f.shells.map((s) =>
        patches.has(s.id) ? { ...s, ...patches.get(s.id) } : s,
      ),
    }));
  for (const s of stalled)
    $.ui.toast(
      `⚠ ${shellName(s.command)} · no output for ${fmtLeft(quietMs(s, now))}`,
    );
  // the band's quiet minutes move with no state change: a redraw a minute
  if (live.some((s) => s.stalled) && now - t.quietDrawnAt >= 60_000) {
    t.quietDrawnAt = now;
    $.ui.invalidate("ui.render");
  }
}

function ensureShellPoll($: EngineInterface, t: Tracker) {
  if (!t.shellPoll)
    t.shellPoll = $.clock.every(SHELL_POLL_MS, () => void watchShells($, t));
}

/** Stops a background shell the way the model would, through TaskStop. */
async function stopShell($: EngineInterface, id: string): Promise<void> {
  await $.tool
    .call({ tool: "TaskStop", task_id: id } as never)
    .catch(() => $.ui.toast(`fleet: could not stop ${id}`));
}

/** A task notification or a turn's end: one agent or shell reached `status`. */
async function endTask(
  $: EngineInterface,
  t: Tracker,
  id: string,
  status: string,
): Promise<void> {
  let agents: FleetAgent[] = [];
  let shell: FleetShell | undefined;
  await update($, fleet, (f) => {
    const now = Date.now();
    const a = applyStatuses(f.agents, { [id]: status }, now);
    const s = endShell(f.shells, id, status, now);
    agents = a.ended;
    shell = s.ended;
    return { ...f, agents: a.agents, shells: s.shells };
  });
  announce($, t, agents, shell ? [shell] : []);
  await settle($, t);
}

async function openPane($: EngineInterface, t: Tracker) {
  const opened = await $.ui.open({ id: PANE, title: `Fleet · ${t.repo}` });
  // an unasked open on a narrow terminal waits undrawn: still "show"
  await update($, pane, () => opened.isPlaced);
  void refreshTrees($, t);
  return opened;
}

/** Closes the pane if the stored state says shown (undefined), opens it if not (how it opened). */
async function togglePane($: EngineInterface, t: Tracker) {
  if (await read($, pane)) {
    await $.ui.close({ id: PANE });
    await update($, pane, () => false);
    return undefined;
  }
  return openPane($, t);
}

const textOf = (content: unknown): string =>
  typeof content === "string"
    ? content
    : Array.isArray(content)
      ? content
          .filter((b) => b?.type === "text" && typeof b.text === "string")
          .map((b) => b.text as string)
          .join("\n")
      : "";

export const register: Register = (on, options) => {
  const t: Tracker = {
    autoOpen: options.autoOpen !== false,
    sound: options.sound !== false,
    telegram: options.telegram !== false,
    idleMs:
      (typeof options.idleMinutes === "number" && options.idleMinutes >= 0
        ? options.idleMinutes
        : 5) * 60_000,
    repo: "",
    root: undefined,
    docks: undefined,
    poll: undefined,
    shellPoll: undefined,
    quietDrawnAt: 0,
  };

  on("session.start", async ($, e, next) => {
    const r = await next(e);
    await $.command.register({
      name: "fleet",
      description:
        "Show or hide the pane with this session's agents, background shells and worktrees",
    });
    const top = await $.process
      .run(["git", "rev-parse", "--show-toplevel"])
      .catch(() => undefined);
    t.root = top?.exitCode === 0 ? top.stdout.trim() : undefined;
    const cwd = await $.session.cwd().catch(() => "");
    t.repo = (t.root ?? cwd).split("/").pop() || "session";
    // the session's start counts as a prompt; a reload keeps the last one
    const started = await $.clock.now();
    await update($, lastPrompt, (at) => at || started);
    // a reload keeps an open pane
    const drawn = await isPaneDrawn($);
    await update($, pane, () => drawn);
    $.clock.every(15_000, async () => {
      let shown = await read($, pane);
      // a waiting pane gets drawn once the terminal widens
      if (!shown && (await isPaneDrawn($))) {
        shown = true;
        await update($, pane, () => true);
      }
      if (shown) await refreshTrees($, t);
    });
    // a reload while agents or shells run: pick the polls up again
    const f = await read($, fleet);
    if (f.agents.some((a) => isLive(a.status))) ensurePoll($, t);
    if (f.shells.some((s) => isLive(s.status) && s.outputFile))
      ensureShellPoll($, t);
    return r;
  });

  on("session.end", async ($, e, next) => {
    if (e.reason === "clear") {
      t.poll?.cancel();
      t.poll = undefined;
      t.shellPoll?.cancel();
      t.shellPoll = undefined;
      await update($, fleet, (f) => ({ ...emptyFleet(), trees: f.trees }));
    }
    return next(e);
  });

  on("command.run", { command: "fleet" }, async ($) => {
    const opened = await togglePane($, t);
    return {
      text: !opened
        ? "Fleet pane closed."
        : opened.isPlaced
          ? "Fleet pane opened."
          : "Fleet pane is waiting for a wider terminal.",
    };
  });

  on("prompt.submit", async ($, e, next) => {
    if (e.origin.kind === "composer") {
      const at = await $.clock.now();
      await update($, lastPrompt, () => at);
    }
    return next(e);
  });

  on("agent.spawn", async ($, e, next) => {
    const r = await next(e);
    if (r.deny !== undefined || !r.agentId) return r;
    const agent: FleetAgent = {
      id: r.agentId,
      type: e.subagentType,
      description: e.description,
      model: r.model,
      startedAt: Date.now(),
      status: "running",
      tools: 0,
      ...(e.isTeammate ? { teammate: true } : {}),
    };
    let open = false;
    await update($, fleet, (f) => {
      const agents = trim([...f.agents, agent]);
      const live = agents.filter((a) => isLive(a.status)).length;
      // unasked, only where the pane is a sidebar; not marked opened, so a later spawn may still
      open = t.autoOpen && t.docks === true && !f.autoOpened && live >= 2;
      return {
        ...f,
        agents,
        batchStart: f.batchStart ?? agent.startedAt,
        autoOpened: f.autoOpened || open,
      };
    });
    ensurePoll($, t);
    if (open && !(await read($, pane))) void openPane($, t);
    return r;
  });

  on("tool.call", async ($, e, next) => {
    if (e.agentId) {
      const id = e.agentId;
      const label = toolLabel(String(e.tool), e);
      await update($, fleet, (f) =>
        f.agents.some((a) => a.id === id)
          ? {
              ...f,
              agents: f.agents.map((a) =>
                a.id === id ? { ...a, lastTool: label, tools: a.tools + 1 } : a,
              ),
            }
          : f,
      );
    }
    const r = await next(e);
    if (e.tool !== "Bash" || r.deny !== undefined) return r;
    const taskId = (r.result as { backgroundTaskId?: string } | undefined)
      ?.backgroundTaskId;
    if (!taskId) return r;
    const outputFile = outputFileOf(r.text);
    const shell: FleetShell = {
      id: taskId,
      command: e.command,
      startedAt: Date.now(),
      status: "running",
      ...(outputFile ? { outputFile } : {}),
      ...(isWaiter(e.command) ? { waiter: true } : {}),
    };
    await update($, fleet, (f) => ({
      ...f,
      shells: trim([...f.shells.filter((s) => s.id !== taskId), shell]),
      batchStart: f.batchStart ?? shell.startedAt,
    }));
    if (outputFile) ensureShellPoll($, t);
    return r;
  });

  // a background task's notification: a shell or an agent finished
  on("session.append", async ($, e, next) => {
    const r = await next(e);
    if (!mayNotify(e.message)) return r;
    const note = parseNotification(textOf(e.message.content));
    if (note) await endTask($, t, note.id, note.status);
    return r;
  });

  // a main turn's end lists the tasks still in flight: a live shell missing
  // from it ended with no notification (a restart, a kill), so it is lost
  on("classic.Stop", async ($, e, next) => {
    const r = await next(e);
    if (!e.background_tasks) return r;
    const inFlight = new Set(e.background_tasks.map((b) => b.id));
    await update($, fleet, (f) => ({
      ...f,
      shells: loseShells(f.shells, inFlight, Date.now()),
    }));
    await settle($, t);
    return r;
  });

  on("turn.complete", async ($, e, next) => {
    const r = await next(e);
    if (!e.agentId) return r;
    const f = await read($, fleet);
    const a = f.agents.find((x) => x.id === e.agentId);
    if (a && !a.teammate && isLive(a.status))
      await endTask(
        $,
        t,
        a.id,
        e.isAborted ? "killed" : e.reason === "error" ? "failed" : "completed",
      );
    return r;
  });

  on("ui.render", { component: "Pane", requestId: PANE }, async ($, e) => {
    const f = await read($, fleet);
    const view: FleetView = {
      repo: t.repo,
      width: e.props.bodyColumns,
      agents: f.agents,
      shells: f.shells,
      trees: f.trees,
    };
    if (e.surface === "terminal" || e.surface === "desktop") {
      const { Box, Button, Client, Text } = $.ui.resolve(e);
      const live = f.shells.filter((s) => isLive(s.status));
      return (
        <Box flexDirection="column">
          <Client key="fleet-body" module="./pane.tsx" props={view} />
          {live.length > 0 && <Text> </Text>}
          {live.map((s) => (
            <Button
              key={`fleet-stop-${s.id}`}
              dimColor
              onPress={() => stopShell($, s.id)}
            >
              {`stop ${shellName(s.command)}`}
            </Button>
          ))}
        </Box>
      );
    }
    return drawFleet($.ui.resolve(e), view, Date.now());
  });

  // its own line under the other bands: the counts and a show/hide toggle
  on("ui.render", { component: "AbovePrompt" }, async ($, e, next) => {
    if (e.viewport?.isFullscreen !== undefined)
      t.docks = e.viewport.isFullscreen;
    const f = await read($, fleet);
    const open = await read($, pane);
    const now = await $.clock.now();
    const empty = f.agents.length === 0 && f.shells.length === 0;
    if (e.props.hasSurvey || (empty && !open)) return next(e);
    const below = await next(e);
    const { Box, Button, Text } = $.ui.resolve(e);
    return (
      <Box flexDirection="column">
        {below}
        <Box flexDirection="row" columnGap={2} marginTop={1}>
          <Text dimColor>
            {[statusLine(f) ?? "fleet", ...shellNotes(f.shells, now)].join(
              " · ",
            )}
          </Text>
          <Button
            key="fleet-toggle"
            hotkey="f"
            dimColor
            onPress={() => togglePane($, t)}
          >
            {open ? "hide" : "show"}
          </Button>
        </Box>
      </Box>
    );
  });

  on("ui.close", { id: PANE }, async ($, e, next) => {
    const r = await next(e);
    await update($, pane, () => false);
    return r;
  });
};

